        uint256 slippageBps;
        uint256 maxPrice;
        uint256 minPrice;
        uint256 endDate;
        uint256 maxTrades;
    }

    struct StrategyState {
        Status status;
        uint248 tradesExecuted;
        uint256 nextTriggerAt;
        uint256 lastScheduledAt;
    }

    function createStrategy(
